begin;
set local search_path=public,extensions;
select plan(12);
insert into accounts(id,slug,name,timezone) values('11610000-0000-4000-8000-000000000001','t10-catalog-test','T10 catalog','Asia/Shanghai');
insert into account_memberships(account_id,user_id,role) select '11610000-0000-4000-8000-000000000001',id,'owner' from auth.users order by id limit 1;
insert into account_blueprint_versions(id,account_id,version,policy,is_active) values('11610000-0000-4000-8000-000000000002','11610000-0000-4000-8000-000000000001',1,'{}',true);
insert into episodes(account_id,blueprint_version_id,title,is_test,updated_at) select '11610000-0000-4000-8000-000000000001','11610000-0000-4000-8000-000000000002','catalog-'||n,true,'2000-01-01' from generate_series(1,1005)n;
select set_config('request.jwt.claim.sub',(select user_id::text from account_memberships where account_id='11610000-0000-4000-8000-000000000001'),true);
set local role authenticated;
create temp table first_page as select read_episode_catalog(p_account_id=>'11610000-0000-4000-8000-000000000001') data;
select is((select jsonb_array_length(data->'episodes') from first_page),20,'only current page sent');
select is((select (data->>'total')::int from first_page),1005,'total exceeds REST ceiling');
select is(jsonb_array_length(read_episode_catalog(p_account_id=>'11610000-0000-4000-8000-000000000001',p_page=>51)->'episodes'),5,'tail page complete');
select is(read_episode_catalog(p_account_id=>'11610000-0000-4000-8000-000000000001',p_page=>999)->>'page','51','deleted/invalid high page clamped');
select is((select data->'episodes' from first_page),read_episode_catalog(p_account_id=>'11610000-0000-4000-8000-000000000001')->'episodes','same timestamp stable unique sort');
select ok(not exists(select 1 from jsonb_array_elements((select data->'episodes' from first_page)) a join jsonb_array_elements(read_episode_catalog(p_account_id=>'11610000-0000-4000-8000-000000000001',p_page=>2)->'episodes') b on a->>'id'=b->>'id'),'adjacent pages disjoint');
select is(read_episode_catalog(p_account_id=>'11610000-0000-4000-8000-000000000001',p_visibility=>'archived')->>'total','0','archive filter on server');
select is(read_episode_catalog(p_account_id=>'11610000-0000-4000-8000-000000000001',p_view=>'reviews')->>'total','0','review stage filter on server');
select is(read_episode_catalog(p_account_id=>'11610000-0000-4000-8000-000000000099')->'episodes','[]'::jsonb,'missing account empty');
select is((select data#>>'{accountCounts,11610000-0000-4000-8000-000000000001}' from first_page),'1005','account total not page size');
reset role;
select set_config('request.jwt.claim.sub','11610000-0000-4000-8000-000000000099',true);
set local role authenticated;
select is(read_episode_catalog(p_account_id=>'11610000-0000-4000-8000-000000000001')->>'total','0','other Owner cannot read counts or rows');
select ok(not has_function_privilege('anon','public.read_episode_catalog(text,integer,uuid,text,text,integer,integer)','execute'),'anonymous forbidden');
select * from finish();
rollback;
